style.css:
@-moz-document domain("youtube.com") {
/* Background and General Colors */
    body, #content {
        background-color: #e0f7fa !important; /* Light pastel blue */
        color: #004d61 !important; /* Darker blue for text */
    }

    /* YouTube Logo */
    #logo-icon-container {
        filter: hue-rotate(180deg) brightness(1.2); /* Slight pastel tint */
    }

    /* Loading Bar */
    .ytp-play-progress {
        background-color: #80deea !important; /* Bright pastel blue */
    }

    .ytp-load-progress {
        background-color: #b2ebf2 !important; /* Faint pastel blue */
    }

    /* Buttons and Icons */
    #buttons, .ytd-button-renderer {
        background-color: #81d4fa !important; /* Soft pastel button */
        border-radius: 5px !important;
        color: #004d61 !important; /* Darker blue text */
    }

    #buttons:hover, .ytd-button-renderer:hover {
        background-color: #4fc3f7 !important; /* Highlighted blue */
    }

    /* Video Titles and Links */
    a.yt-simple-endpoint {
        color: #0277bd !important; /* Vibrant blue for links */
    }

    a.yt-simple-endpoint:hover {
        color: #01579b !important; /* Darker blue on hover */
    }

    /* Video Thumbnails */
    ytd-thumbnail {
        border: 2px solid #81d4fa !important; /* Blue border around thumbnails */
        border-radius: 8px !important; /* Smooth corners */
    }

    /* Header and Navbar */
    #masthead-container {
        background-color: #e1f5fe !important; /* Lighter pastel header */
        border-bottom: 2px solid #81d4fa !important;
    }

    /* Sidebar */
    #guide-content {
        background-color: #b3e5fc !important; /* Soft sidebar background */
        color: #004d61 !important;
    }

    #guide-content a {
        color: #0288d1 !important;
    }

    /* Comments Section */
    #comments {
        background-color: #f1f8ff !important; /* Light pastel background */
        border-top: 2px solid #81d4fa !important;
    }

    /* Footer */
    #footer-container {
        background-color: #81d4fa !important;
        color: #004d61 !important;
    }

    /* Scrollbar */
    ::-webkit-scrollbar {
        width: 8px;
    }
    ::-webkit-scrollbar-thumb {
        background-color: #81d4fa; /* Pastel blue scrollbar */
        border-radius: 5px;
    }
    ::-webkit-scrollbar-thumb:hover {
        background-color: #4fc3f7; /* Highlighted blue scrollbar */
    }
}
